package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.JdbcReportSupplementActions;
import com.lianxibu.site.controller.content.ContentDtos;
import org.junit.jupiter.api.Test;
/** Pure public metadata projections from the original fictional H2 native acceptance. */
class ReportSupplementResponseTest {
 @Test void OriginalIntentAndActionWireStayImmutableAfterLaterBodyAndSlotChanges()throws Exception{var h=new ReportSupplementPreparationTest();h.setup(true);var result=h.prepare("fictional-response");var job=ReportSupplementResponse.job(result);var action=ReportSupplementResponse.action(result);assertEquals("generation_intent",job.recordKind());assertEquals(result.accepted().intentId(),job.id());assertEquals("ready",job.inputState());assertEquals(result.accepted().intentRevision(),job.revision());assertEquals(result.accepted().intentRevision(),job.intentRevision());assertEquals(result.accepted().cutoff(),job.inputCutoffAt());assertEquals(0,job.callCount());assertNull(job.maxAttempts());assertEquals(result.accepted().slotState(),job.slotState());assertEquals(result.accepted().baseRevision().longValue(),action.resultRevision());assertEquals(result.accepted().contentId(),action.resultResourceRef().id());assertEquals(2L,action.generation());assertEquals(2,action.affected().size());assertEquals("generation_intent",ContentDtos.job(job).get("record_kind"));assertEquals(2L,ContentDtos.action(action).get("generation"));var f=h.h.h.h.h.f.data.nativeData().fixture().f();f.jdbc.update("UPDATE worker_lock SET slot_revision=slot_revision+1");f.jdbc.update("UPDATE contents SET revision=revision+1,state='blocked'");assertEquals(job,ReportSupplementResponse.job(result));assertEquals(action,ReportSupplementResponse.action(result));assertThrows(UnsupportedOperationException.class,()->job.coverage().missingInputs().clear());assertEquals(1,h.h.reportSends);}
 @Test void NoInputAndAbsentTargetHaveExactOriginalCoverageWithoutBodyOrNoUpdateAuthority()throws Exception{var h=new ReportSupplementPreparationTest();h.setup(false);var result=h.prepare("fictional-response-absent");assertNull(result.accepted().baseRevision());assertThrows(RuntimeException.class,()->ReportSupplementResponse.action(result));assertEquals(result.accepted().contentId(),ReportSupplementResponse.job(result).contentId());var f=h.h.h.h.h.f.data.nativeData().fixture().f();assertEquals(0L,f.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE id=?",Long.class,h.id));h=new ReportSupplementPreparationTest();h.setup(true);f=h.h.h.h.h.f.data.nativeData().fixture().f();f.jdbc.update("UPDATE contents SET state='blocked' WHERE kind='agent'");h.preferences=new FrozenGenerationSettings(1,java.util.List.of(),java.util.List.of());var empty=h.prepare("fictional-response-no-input");var job=ReportSupplementResponse.job(empty);assertEquals("no_input",job.inputState());assertEquals("no_input",job.coverage().state());assertTrue(job.coverage().noUpdateDates().isEmpty());assertTrue(job.attempts().isEmpty());assertEquals(0,h.builds);}
 @Test void ForgedAcceptanceCannotChangeContentIdentityOrBorrowTheOriginalInput()throws Exception{var h=new ReportSupplementPreparationTest();h.setup(true);var result=h.prepare("fictional-response-identity");var a=result.accepted();var bad=new JdbcReportSupplementActions.Accepted(a.operationId(),a.rootId(),a.intentId(),a.generation(),a.intentRevision(),"fictional-alias",a.baseRevision(),a.cutoff(),a.inputHash(),a.businessInputHash(),a.state(),a.originalReceiptHash(),a.slotState(),a.slotRevision(),a.occupiedAttemptId());var wrong=new ReportSupplementPreparationService.Result(bad,result.prepared());assertThrows(RuntimeException.class,()->ReportSupplementResponse.job(wrong));assertThrows(RuntimeException.class,()->ReportSupplementResponse.action(wrong));}
}
